# Check for potential vulnerabilities in the encryption function
def test_encrypt_data():
    try:
        # Test with a short key
        encrypt_data(b'short', b'some data')  # Should raise ValueError
    except ValueError as e:
        print(f"Expected error for short key: {e}")

    try:
        # Test with non-byte data
        encrypt_data(b'longenoughkey123', 'not bytes')  # Should raise ValueError
    except ValueError as e:
        print(f"Expected error for non-byte data: {e}")

# Run the test
test_encrypt_data()

